insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-690-4','APX-C-690',4,8,11,3,'Scene 4: 8–11s Fast montage, approximately 0.5 seconds per frame—Drifting on a rainy night, water splashing / Breaking ice in the snow, moving forward resolutely / Sunset in the desert, car and person silhouetted together. Strong light and shadow contrast, epic texture.','A rapid-fire montage carries him through the elements -- drifting through rain-soaked streets, breaking through snow and ice, and crossing a desert at sunset.','driver','driving','none','none','rain-soaked road, snowy terrain, desert at sunset','wide',NULL,'none','speed-ramp','mixed dramatic lighting','water','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-690-5','APX-C-690',5,11,13,2,'Scene 5: 11–13s The car slowly stops in front of an old house. The door opens, and a little girl runs out, her laughter arriving before her. The man squats down and opens his arms. Handheld follow shot, gentle landing.','The car pulls up to an old house, and a little girl runs out laughing as the man kneels down and opens his arms to her.','family','none','none','none','old house driveway','medium','eye','handheld','real-time','warm dusk light','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
