insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4719-1','APX-C-4719',1,0,2,2,'Black screen. Soft sound of rain outside. One salon light turns on in darkness. Then another. Then another. Wide cinematic shot reveals an empty luxury beauty studio before opening hours. One woman unlocks the glass entrance while the other silently arranges makeup brushes beside glowing mirrors. Text Overlay: “No investors. No shortcuts. Just belief.” Sound: Emotional piano intro + soft rain ambience 2–5 SEC:','Out of darkness, salon lights flick on one by one to reveal an empty luxury beauty studio before opening as one woman unlocks the door and the other quietly sets out brushes, over a line about building on belief.',NULL,'none','none','none','luxury beauty salon before opening','wide','eye','static','real-time','soft light rising in darkness','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
