insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5504-2','APX-C-5504',2,NULL,NULL,NULL,'Then, it descends greatly toward the harbor on the left and flies at low altitude just above the water surface. It makes a wide detour along the waterway, skimming past sea reflections, waves, yachts, piers, wharves, and harbor buildings. ','It dives toward the harbor and skims just above the water, making a wide detour past sea reflections, waves, yachts, piers and harbor buildings.','driver','none','none','none','harbor waterways','wide','low','fpv','real-time','sparkling water reflections','water','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5504-3','APX-C-5504',3,NULL,NULL,NULL,'After the detour, it accelerates further toward the magnificent white and gold tower in the center. After passing between the buildings, the moment the tower is captured in front, the nose is suddenly raised for a steep climb. In POV, it races up the side of the tower''s spire, the details of the tower flowing by at high speed, and a panoramic view of the city and harbor spreads out below. ','It accelerates toward the great white-and-gold central tower, passes between buildings, then suddenly pitches up to race along the spire as a panorama of the city and harbor opens below.','driver','none','none','none','central tower and city','wide','low','fpv','real-time','bright daylight','none','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
