insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5470-1','APX-C-5470',1,NULL,NULL,NULL,'Starting from the sea on the left, the camera rushes along the blue harbor at a low angle just above the water surface. Passing between yachts, piers, white ships, and port architecture, it crosses the seaside city from left to center at high speed. ','The flight starts out at sea and rushes low over the blue harbor, weaving between yachts, piers and white ships as it crosses the seaside city at high speed.',NULL,'none','none','none','white-and-gold port city harbor','wide','low','fpv','real-time','bright daylight, water reflections','water','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5470-2','APX-C-5470',2,NULL,NULL,NULL,'It then accelerates toward the giant cathedral in the center, approaching it while skimming over the buildings. Just before passing the front of the cathedral, the camera ascends sharply along the main tower. It rises with the power of looking straight up from below the spire, transitioning to a grand bird''s-eye view of the entire city, harbor, and distant mountain range. ','It accelerates toward the great central cathedral, skimming the rooftops, then climbs sharply straight up the main tower to open into a grand aerial view of the city, harbor and distant mountains.',NULL,'none','none','none','central cathedral and city','wide','low','fpv','real-time','bright sunlight','none','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5470-3','APX-C-5470',3,NULL,NULL,NULL,'After passing the top of the tower, the camera turns while banking heavily to the right. Keeping the cathedral tower in the center, it dynamically moves clockwise, showing the white palace-like streets, blue sea, bridges, port facilities, and distant mountains in a fluid motion. ','Passing the tower top, the flight banks hard right and sweeps clockwise around the spire, revealing white palace streets, blue sea, bridges and mountains in one fluid motion.',NULL,'none','none','none','above the port city','wide','high','orbit','real-time','bright daylight','none','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
