insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5299-3','APX-C-5299',3,4,6,2,'4-6s: Crash zoom to monkeys in palm trees dropping coconuts. The camera follows coconuts bouncing beside the car in slow motion, then speed ramps back to fast action.','A crash zoom hits monkeys dropping coconuts, the camera following them bouncing in slow motion before snapping back to fast action.','animal-character','driving','none','none','village road by palm trees','medium','eye','push-in','speed-ramp','bright sunlight','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
