insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-890-2','APX-C-890',2,NULL,NULL,NULL,'the character is full of presence, delivering a passionate, unscripted speech throughout, with a powerful and rhythmic tone, progressively fitting the script''s pace, cutting to a close-up at 3 seconds to capture the resolute expression of clenching a fist and raising an arm; accurately reciting the lines: Don''t you dare not believe it, when you are getting better and better, you will come across me, since you have come across me, repeat after me, my 2026 will get better and better, and it will truly be excellent; when saying "my 2026 will get better and better, and it will truly be excellent," raise an arm and clench a fist for emphasis;','She delivers a rousing, rhythmic speech with total presence, the view tightening on her resolute expression as she clenches a fist and raises her arm for emphasis on the speech''s climactic line.',NULL,'none','none','none','stadium stage','cu','low','push-in','real-time','stage light','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
