insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4494-2','APX-C-4494',2,5,10,5,'Her dance becomes more expressive—spins, arm sweeps, and jumps create long flowing ink trails. Watercolor reds, blues, and gold tones begin blending with black ink, forming chaotic yet beautiful brush textures across the scene. 10–15s:','Her movements grow bolder, spins and sweeping arms leaving long flowing trails as reds, blues and gold begin blending with the black ink.',NULL,'none','none','none','white canvas space','medium','eye','tracking','slow-mo','soft even light','particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
