insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3345-3','APX-C-3345',3,NULL,NULL,NULL,'By 2s, the viewer''s hands enter the frame, loading a fork with food dipped in Carolina Reaper-infused oil, a vivid dark red condiment. The fork extends towards the Chef, who grins and takes the bite at 5s, enjoying the flavor,','The camera-holder''s own hands load a fork with a bite dipped in a fiery-looking dark red condiment and offer it across the table; the chef grins and takes the bite, enjoying it at first.','chef','biting','condiment-dipped bite','featured','kitchen dining table','cu','pov','static','real-time','warm amber and white light','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
