insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3345-5','APX-C-3345',5,NULL,NULL,NULL,'At 10s, he slams a palm onto the table, grabs rice desperately, and at 12s laughter erupts from behind the camera, shaking it violently. The Chef stares into the camera at 13s, eyes watering, pointing an accusatory finger, before he angrily throws the ramekin off at 14s, maintaining a fierce glare at the camera.','He slams his palm on the table and grabs at rice for relief while laughter erupts from behind the camera, shaking the shot.','chef','none','rice','incidental','kitchen dining table','medium','pov','handheld','real-time','warm amber and white light','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3345-6','APX-C-3345',6,NULL,NULL,NULL,'The single continuous shot highlights his escalating reaction, capturing the authenticity of the moment with natural kitchen noises like sizzling and clinking throughout. The camera remains steady until 12s when it shakes from laughter, stabilizing during the Chef''s furious gaze. The scene retains practical lighting and sound without artificial effects, ending on the Chef''s intense stare, the ambient kitchen sounds undisturbed, a master chef clearly pranked.','The chef glares straight into the camera, eyes watering, pointing accusingly before flinging the condiment dish aside — a good-natured kitchen prank caught in one unbroken take.','chef','none','none','none','kitchen dining table','cu','pov','handheld','real-time','warm amber and white light','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
