insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2682-3','APX-C-2682',3,6,9,3,'[6-9s] Shibuya scramble crossing at night. Camera starts low in the crowd, spins 360 degrees fast at hip level — people and neon signs streak past — then rapidly cranes straight up into the air, rising fast to reveal the full intersection below. The spin-to-rise transition is sudden and energetic.','Starting low in the crowd at Shibuya''s scramble crossing, the camera spins fast at hip level through streaking neon signs, then cranes rapidly upward to reveal the full intersection.',NULL,'none','none','none','Shibuya scramble crossing at night, Tokyo','wide','low','crane','speed-ramp','neon signage','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2682-4','APX-C-2682',4,9,12,3,'[9-12s] A shinkansen N700 bullet train. Camera holds static for a split second — then the train BLASTS past at full speed inches from the lens, the shockwave shaking the frame violently. Camera immediately whips to track it from behind, accelerating to match speed, rice fields streaking.','A Shinkansen bullet train blasts past inches from the static camera, the shockwave shaking the frame before the camera whips around to track it from behind through streaking rice fields.',NULL,'racing','none','none','rural trackside, Shinkansen bullet train, Japan','wide','low','tracking','real-time','daylight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
