insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3046-1','APX-C-3046',1,NULL,NULL,NULL,'The [apple] splits horizontally exactly at the middle height (50:50). The top and bottom halves are the same height. The top half rises while maintaining the shape of the top of the [apple]. The bottom half remains fixed on the table and does not move, maintaining the shape of the bottom of the [apple]. Only one top half exists, no duplication or splitting.','An apple sitting on a table splits cleanly in half, top and bottom equal, with the top half rising smoothly while the bottom stays put.',NULL,'none','apple','hero','tabletop, plain background','medium','eye','static','real-time','soft studio lighting','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3046-2','APX-C-3046',2,NULL,NULL,NULL,'A [white cat] appears from the gap and stands on both feet on the edge of the top surface of the bottom half. The body is outside the bottom half and not buried in the [apple]. It stretches both front paws upward to support the bottom surface of the top half and pushes it overhead. No cuts, no teleportation, smooth transformation.','A white cat pops up from the gap between the two apple halves and braces itself on the edge, using both paws to hold the top half aloft.','animal-character','none','apple','hero','tabletop, plain background','medium','eye','static','real-time','soft studio lighting','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3046-3','APX-C-3046',3,NULL,NULL,NULL,'After appearing, the [white cat] continues to support the top half overhead with both front paws, and its feet do not leave the edge of the bottom half. It does not jump. It does not lift its feet. It only continues to swing its hips rhythmically left and right. The top half remains stationary overhead without shaking. The composition always maintains this order: [Object / Bottom half / Fixed] - [Character body / Exposed on the outside] - [Object / Top half / Overhead / Only one].','The cat keeps holding the top half of the apple overhead without wavering, and instead starts swaying its hips rhythmically to the beat.','animal-character','none','apple','hero','tabletop, plain background','medium','eye','static','real-time','soft studio lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
