insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1790-4','APX-C-1790',4,13,15,2,'Pull back to a full shot, warm light in the mahjong hall, tea smoke curling up. The four continue shuffling and stacking tiles. After a close-up of the massaging girls'' hands, the camera Gradual Pulls Out slowly to end. Sound effects include shuffling tiles, scattered dialogue, and fading background music.','The camera pulls back to take in the warmly lit hall as the friends shuffle tiles for another round, tea steam curling in the air.','guest','none','tea','incidental','Chengdu mahjong hall','wide','eye','pull-back','real-time','warm chandelier light','steam','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
