insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4893-4','APX-C-4893',4,NULL,NULL,NULL,'She takes a step forward, her wrist turning slightly, and the scepter swings from her side to her front, the white gauze sleeves rising with the movement like petals unfolding. The scepter cuts through the air, leaving a faint dark red light trail.','She steps forward and swings the scepter from her side to the front, gauze sleeves rising like petals and a faint dark-red trail cutting the air.','guest','none','none','none','cathedral','medium','eye','none','slow-mo','moonlight','energy;particles','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4893-5','APX-C-4893',5,NULL,NULL,NULL,'Then she begins to dance with the scepter, the movements combining dance and combat: spinning, looking back, sweeping low, crouching, and standing back up with a reverse grip. As the scepter sweeps across the floor, the fog is cut open, and dust and smoke disperse to the sides.','She begins a dance that blends movement and combat — spinning, sweeping low and rising with a reverse grip — the scepter parting the fog across the floor.','guest','none','none','none','cathedral','wide','eye','orbit','real-time','moonlight through fog','particles','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4893-6','APX-C-4893',6,NULL,NULL,NULL,'The mid-section camera becomes more powerful, with low-angle shots. As she spins, the scepter flips over her shoulder, the black shiny leather pants reflect cold light, and the white ruffled cuffs fly apart in slow motion.','Low, powerful angles follow her spins as the scepter flips over her shoulder and the ruffled cuffs fly apart in slow motion.','guest','none','none','none','cathedral','medium','low','none','slow-mo','cold moonlight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4893-7','APX-C-4893',7,NULL,NULL,NULL,'Climax Section: She spins the scepter at high speed, the ruby head forming a ring of dark red energy, the smoke swirled into a vortex, and moonlight, red light, and dust particles intertwine. The camera circles around her, the image filled with a sense of pressure and elegant killing intent.','At the climax she spins the scepter fast, the ruby forming a ring of dark-red energy as smoke swirls into a vortex and the camera circles her.','guest','none','none','none','cathedral','medium','eye','orbit','real-time','moonlight and red glow','energy;particles','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4893-8','APX-C-4893',8,NULL,NULL,NULL,'Finally, she stops suddenly, the tip of the scepter pointing at the camera, her eyes looking directly at the audience, and the camera zooms in quickly. Then she raises the scepter over her head, the ruby meeting the moonlight from the window, a brief flash appears in the air, and dust scatters like stardust.
