insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-451-6','APX-C-451',6,NULL,NULL,NULL,'Then she lowers her head and continues eating the hot pot, with a natural and relaxed expression.','She lowers her head and goes back to eating, relaxed and at ease.','guest','none','spicy hot pot','hero','rented apartment living room','medium','low','static','real-time','warm yellow indoor light','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3527-1','APX-C-3527',1,0,2,2,'[00:00-00:02] Shot 1: Nightclub Queen (Slow-mo Entrance)\n[Japanese Narration] Low female voice: ''In the night of this city, three stories are breathing.''\nSlow-mo Medium Shot: Dim nightclub backstage, newspaper-plastered walls, tungsten bulbs casting warm, harsh light. Female A with one hand on hip, fur sliding from shoulder to elbow, tilts her head slightly, glancing at the camera over her sunglasses with a cold smirk. Gold earrings sway with her head movement, reflecting tiny points of light.\n\n','In a dim club backroom lit by warm bulbs, a cold, glamorous woman rests a hand on her hip, lets her fur coat slide to her elbow, and glances over her sunglasses with a smirk as her earrings catch the light.',NULL,'none','none','none','dim nightclub backstage','medium',NULL,'none','slow-mo','warm tungsten bulbs','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3527-2','APX-C-3527',2,2,6,4,'[00:02-00:06] Shot 2: Late-night Solitude (Intimate Moment)\n[Japanese Narration]: ''One person hides a face they show to no one.''\nMedium Close-up Side Shot: Warm lamp light interlaced with cold blue moonlight from outside. Female B sits on the edge of the bed, one hand gently clutching the sweater collar, orange-red long hair falling over shoulders and chest, she looks down with eyes slightly closed, eyelashes casting shadows. Pearl necklace glows slightly at the collarbone. City lights outside the window blur into bokeh.\n\n','A quiet woman sits on the edge of a bed in mixed warm lamp and cool moonlight, clutching her sweater collar and looking down with eyes nearly closed as city lights blur beyond the window.',NULL,'none','none','none','apartment bedroom at night','cu',NULL,'none',NULL,'warm lamp and cold blue moonlight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3527-3','APX-C-3527',3,6,10,4,'[00:06-00:10] Shot 3: Office Breaking Point\n[Japanese Narration]: ''One person is not even allowed to cry.''\nFrontal Medium Shot Slow Dolly In: A cold white fluorescent-lit office, empty after work. Female C leans against the desk, hands clenched at her sides, knuckles white. The camera slowly pushes toward her face — eyes red, tears welling but held back, lips trembling slightly, jaw tight. The tie is pulled loose, shirt collar slightly open.\n\n','In an empty, cold-lit office after hours, a woman leans against a desk with clenched fists, eyes red and lips trembling as the camera slowly pushes toward her face while she holds back tears.',NULL,'none','none','none','empty office at night','medium',NULL,'push-in',NULL,'cold white fluorescent','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3527-4','APX-C-3527',4,10,13,3,'[00:10-00:13] Shot 4: Triple Cross-Cut (Rapid Cross-Cut)\n[Japanese Narration]: ''Even so—''\nJump Cut alternating three sets of images: \nFemale A suddenly turns and pushes open the nightclub door into the night, fur fluttering in the wind—\nFemale B looks up at the moonlight outside, expression turning from gentle to firm—\nFemale C wipes a tear from the corner of her eye with the back of her hand, takes a deep breath and straightens her back—\nEach image 1 second, rhythm accelerating with low-frequency drum beats.\n\n','Rapid cross-cuts alternate the three women as each turns a corner: one pushes out into the night, one looks up with new resolve, and one wipes a tear and straightens up, the rhythm quickening.',NULL,'none','none','none','three intercut locations','medium',NULL,'none',NULL,'','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3527-5','APX-C-3527',5,13,15,2,'[00:13-00:15] Shot 5: Final Frame\n[Japanese Narration]: ''They do not stop.''\nTriple Split Screen: Left - Female A walking backlit on the street; Middle - Female B standing by the window in profile; Right - Female C in the elevator looking straight into the lens. All three freeze simultaneously.\nBlack screen, white Japanese handwritten subtitles appear: ''Three nights, three kinds of strength.''','A three-way split screen shows all three women — on the street, by a window, and in an elevator — freezing at once before the frame goes black and a handwritten line appears.',NULL,'none','none','none','split-screen finale','medium',NULL,'none',NULL,'','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
