insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5109-1','APX-C-5109',1,0,2,2,'Shot 1 (0:00-0:02): Image2 as first frame. Drone plunges over Camp Nou, 80,000 fans, floodlights against deep blue dusk sky. Speed ramp decelerates to 40% at grass level. Anamorphic lens flare. Audio: stadium roar. Hard cut.','A drone plunges over a packed stadium at dusk, gliding down to grass level under blazing floodlights.',NULL,'none','none','none','packed stadium at dusk','extreme-wide','high','drone','speed-ramp','floodlights against deep blue dusk','lens-flare','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
