insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5109-5','APX-C-5109',5,9,11,2,'Shot 5 (0:09-0:11): Resolves from flash. Image3 screams through air at 15% speed, turf particles trailing. 200mm telephoto tracking ball. Real Madrid goalkeeper dives full stretch — too late. Ball strikes top corner, net bulges violently. Audio: net snap, crowd eruption. Hard cut.','The ball screams through the air trailing turf as the keeper dives too late and it strikes the top corner, bulging the net.',NULL,'none','none','none','the goalmouth','medium','eye','tracking','slow-mo','floodlights','particles','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
