insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4108-5','APX-C-4108',5,13,15,2,'Camera shifts and tilts trying to follow. A luxury convoy becomes partially visible: a low-profile angular sports car in front, followed by two large premium SUVs. A security member opens a vertical-style door. The main character enters quickly. Engine revs naturally. Vehicles begin moving forward. Camera lifts slightly as people try to capture the moment.','The view tilts to follow as a low sports car and two large SUVs come into view; a door is opened, the figure steps in and the convoy pulls away.','guest','none','none','none','airport pickup, convoy','wide',NULL,'handheld;tilt',NULL,'natural daylight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
