insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-187-2','APX-C-187',2,1,3,2,'【00:01 - 00:03】Shot 2: Medium Shot (Medium Shot), 【Action】The woman in red quickly spins to evade, the man in white chases with his sword. The background is a dense, emerald bamboo forest, with falling leaves. Wuxia action, graceful, sense of speed, Hanfu.','The woman in red spins away from an attack while the man in white presses his pursuit through falling leaves.',NULL,'none','none','none','dense bamboo forest','medium','eye','tracking','real-time','cool forest light','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-187-3','APX-C-187',3,3,5,2,'【00:03 - 00:05】Shot 3: Low Angle (Low Angle), 【Action】The woman in red slides backward, narrowly dodging a fatal blow close to the ground. Dust flies up from the ground, the camera follows the movement. Sliding, thrilling dodge, dynamic composition.','The woman in red slides low along the ground to narrowly dodge a strike, kicking up dust as the camera follows.',NULL,'sliding','none','none','bamboo forest floor','medium','low','tracking','real-time','cool forest light','particles','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
