insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-187-5','APX-C-187',5,8,11,3,'【00:08 - 00:11】Shot 5, Extreme Close-up (ECU), 【Action】Focusing on the upper bodies of the two, the longsword is held horizontally against the woman''s neck. The woman''s eyes are resolute, the man''s expression is calm (wearing glasses). Eye contact, tense atmosphere, detail depiction.','In tight close-up, a blade rests against her neck; her eyes stay resolute while his expression remains calm behind his glasses.',NULL,'none','none','none','clearing in the bamboo forest','ecu','eye','static','real-time','cool forest light','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
