insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2365-1','APX-C-2365',1,0,1,1,'Scene 1 (0-1s) ✨ Atmosphere setup. Visuals: Overhead shot of the entire high-end restaurant, warm yellow candlelight flickering, soft light refracted by crystal glasses, exquisite French cuisine on a black velvet tablecloth. The wife, wearing a velvet dress, is looking down cutting steak. The husband gazes at her tenderly, his fingertips stroking the velvet gift box. Sound effects: Soft jazz BGM in the restaurant, the faint sound of cutlery touching the porcelain plate. Dialogue: Husband (low and gentle): “My dear, you’ve worked hard today.”','An overhead view sets the scene at an elegant, candlelit restaurant table, where the wife quietly cuts into her dinner while her husband watches her fondly, resting his hand on a wrapped gift box.','guest','none','French cuisine','incidental','high-end restaurant','extreme-wide','overhead','none','real-time','candlelight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2365-2','APX-C-2365',2,2,3,1,'Scene 2 (2-3s) 🎧 Surprise reveal. Visuals: Close-up of the husband slowly pushing the velvet gift box over. The wife looks up, stunned, her eyelashes fluttering. The husband opens the box lid, revealing custom luxury headphones (metallic texture + engraved details) glowing with a cold, high-end light in the candlelight. Sound effects: BGM fades, the soft sound of the box opening, the wife''s sharp intake of breath. Dialogue: Wife (choked up): “Is this…?” Husband: “You always said it was noisy wearing headphones while working overtime. With these, you’ll only hear my voice.”','He slides the gift box across the table; she looks up, surprised, as he opens it to reveal a pair of elegant, custom headphones glowing softly in the candlelight.','guest','none','none','none','high-end restaurant','cu','eye','push-in','real-time','candlelight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2365-3','APX-C-2365',3,4,5,1,'Scene 3 (4-5s) 😭 Emotional climax. Visuals: Close-up shot of the wife''s face, tears streaming down her cheeks. She raises her hand to cover her mouth, her eyes filled with surprise and emotion. The husband gently wipes away her tears. Sound effects: BGM rises in pitch, adding gentle piano music, the wife''s subtle sobs. Dialogue: Wife (crying and smiling): “How did you know I’ve wanted this for so long…”','Overcome with emotion, she tears up, covering her mouth as he gently wipes her tears away.','guest','none','none','none','high-end restaurant','cu','eye','none','real-time','candlelight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2365-4','APX-C-2365',4,6,7,1,'Scene 4 (6-7s) 💞 Romantic conclusion. Visuals: Close-up of the husband taking the headphones and carefully placing them on his wife, his fingertips lightly touching her earlobe. The wife closes her eyes and smiles. As the headphones fit her ears, the camera pulls back to their clasped hands, the candlelight blurring their shadows into a gentle silhouette. Sound effects: BGM reaches a climax then fades, leaving only the sound of their breathing. Dialogue: Husband (softly): “From now on, no matter how noisy the world is, I’ll be right here by your ear.”','He carefully places the headphones on her, and as she closes her eyes and smiles, the camera pulls back to their clasped hands silhouetted by candlelight.','guest','none','none','none','high-end restaurant','cu','eye','pull-back','real-time','candlelight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
