insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2006-2','APX-C-2006',2,3,6,3,'Low close tracking shot on the same donut rolling fast over the shiny floor. Judy bursts into frame from behind, clipboard tucked under one arm, sprinting hard with both paws reaching forward. She almost grabs it but misses by centimeters. The donut keeps rolling. Quick readable camera adjustment, no chaotic motion.','The determined officer sprints hard after the rolling donut, reaching for it but narrowly missing.','agent','sprinting','jelly donut','hero','police station lobby','cu','low','tracking','real-time','warm indoor daylight','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
