insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2006-4','APX-C-2006',4,9,12,3,'Frontal medium-close shot. The donut rolls toward camera. Nick’s paw enters calmly from frame right and presses the same donut to a stop. Judy slides in from frame left and freezes with her nose just inches from it, still in full arrest pose. Hold the reaction beat clearly.','The calm partner casually stops the donut just as the sprinting officer skids to a halt inches away from it, still in full pursuit posture.','agent','sliding','jelly donut','hero','police station lobby','medium','eye','none','real-time','warm indoor daylight','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
