insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2130-3','APX-C-2130',3,NULL,NULL,NULL,'The assassin attacks again, the man blocks with his sword and counterattacks. His swordsmanship is fierce like a swimming dragon, his movements are agile, with realistic impact, sparks flying everywhere, cinematic action long take, strong visual impact, dust flying on the brick floor.','The attacker strikes again and the swordsman parries and counters with fast, fluid strikes, sparks flying as dust rises off the floor.',NULL,'none','none','none','dilapidated night temple','medium','eye','handheld','real-time','flickering candlelight','sparks;particles','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
