insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2147-1','APX-C-2147',1,0.0,2.5,2.5,'Extreme low-angle tracking shot — a hyper-focused street female food chef sprints at impossible speed through a neon-lit Tokyo alley, clutching a steaming bowl of ramen. Crisp apron flapping, sleeves rolled, sneakers splashing through puddles. Camera shakes aggressively behind them. Steam trails like smoke. Neon signs streak across frame. Their face — intense, locked-in, slightly unhinged determination.','A determined chef sprints through a glowing Tokyo alley at breakneck speed, carefully cradling a steaming bowl of ramen through puddles and neon light.','chef','sprinting','ramen','hero','neon-lit Tokyo alley','cu','low','tracking;handheld','real-time','neon','steam','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2147-2','APX-C-2147',2,2.6,5.0,2.4,'Whip-pan — they shoulder-check a stack of plastic crates. TIME REMAP: slow-motion chaos — vegetables, bowls, and chopsticks explode into the air. Broth ripples in perfect cinematic detail without spilling. They tilt the bowl mid-run, saving every drop. Quick glance back, dead serious. Continue sprint.','She clips a stack of crates, sending vegetables and utensils flying, but keeps the bowl perfectly steady without spilling a drop before pushing on.','chef','sprinting','ramen','hero','neon-lit Tokyo alley','medium','eye','whip-pan','slow-mo','neon','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
